CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE source_type AS ENUM ('upload', 'direct_url', 'platform_url');
CREATE TYPE media_type AS ENUM ('video', 'audio');
CREATE TYPE job_mode AS ENUM ('whole_media', 'find_moments', 'transcribe_only');
CREATE TYPE job_status AS ENUM ('queued', 'processing', 'completed', 'failed', 'cancelled');
CREATE TABLE media_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type source_type NOT NULL, media_type media_type NOT NULL, uri text NOT NULL, provider text, metadata jsonb NOT NULL DEFAULT '{}', legacy_provider text, legacy_project_id text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((source_type <> 'platform_url') OR provider IS NOT NULL));
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES media_sources(id), storage_key text NOT NULL UNIQUE, content_type text, byte_size bigint, public_reference text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE processing_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES media_sources(id), mode job_mode NOT NULL, status job_status NOT NULL DEFAULT 'queued', idempotency_key text NOT NULL UNIQUE, attempts integer NOT NULL DEFAULT 0, claimed_at timestamptz, lease_expires_at timestamptz, last_error text, completed_at timestamptz, progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), result jsonb, legacy_provider text, legacy_project_id text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX processing_jobs_claim_idx ON processing_jobs(status, lease_expires_at, created_at);
CREATE TABLE transcripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES processing_jobs(id), asset_id uuid REFERENCES assets(id), language text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transcript_segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transcript_id uuid NOT NULL REFERENCES transcripts(id), start_seconds numeric NOT NULL, end_seconds numeric NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_seconds >= start_seconds));
CREATE TABLE clip_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES processing_jobs(id), start_seconds numeric NOT NULL, end_seconds numeric NOT NULL, score numeric, metadata jsonb NOT NULL DEFAULT '{}', legacy_provider text, legacy_clip_id text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_seconds >= start_seconds));
CREATE TABLE clip_renders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES clip_candidates(id), asset_id uuid REFERENCES assets(id), status job_status NOT NULL DEFAULT 'queued', legacy_provider text, legacy_clip_id text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid REFERENCES clip_candidates(id), render_id uuid REFERENCES clip_renders(id), status text NOT NULL, reviewer text, notes text, legacy_curation_id text, raw_provider_payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
